def search_pdf(path, query):
    doc = fitz.open(path)
    print(f'=== {path} ({len(doc)} pages) ===')
    for page_num in range(len(doc)):
        text = doc[page_num].get_text()
        if query.lower() in text.lower():
            print(f'--- Page {page_num + 1} ---')
            for line in text.split('\n'):
