import os

def search_all_files(dir_path, query):
    for root, dirs, files in os.walk(dir_path):
        for f in files:
            p = os.path.join(root, f)
            if f.endswith(('.pdf', '.docx', '.xlsx', '.eml', '.txt')):
                try:
                    if f.endswith('.pdf'):
                        import fitz
                        doc = fitz.open(p)
                        text = ' '.join([page.get_text() for page in doc])
                    elif f.endswith('.docx'):
                        import docx
                        d = docx.Document(p)
                        text = ' '.join([para.text for para in d.paragraphs])
                    elif f.endswith('.xlsx'):
                        import openpyxl
                        wb = openpyxl.load_workbook(p, data_only=True)
                        text = ''
                        for s in wb.sheetnames:
                            sheet = wb[s]
                            for row in sheet.iter_rows(values_only=True):
                                text += ' '.join([str(v) for v in row if v is not None]) + ' '
                    elif f.endswith('.eml'):
                        with open(p, errors='ignore') as ef:
                            text = ef.read()

                    if query.lower() in text.lower():
                        print(f'Match in {p}')
                except Exception as e:
                    pass

print('=== Searching for spillway ===')
search_all_files('/filesystem', 'spillway')
print('=== Searching for freeboard ===')
search_all_files('/filesystem', 'freeboard')
